sources.TouchReader.ets:
export class TouchReader {
 onTouch(event: TouchEvent): void {
  const finger = event.touches[0]
  this.x = finger.x
 }
}

sources.ConsoleSink.ets:
export class ConsoleSink {
 report(error: Error): void {
  console.error('touch interaction failed', error)
 }
}

sources.AuditPage.ets:
import { ConsoleSink } from './ConsoleSink'
export class AuditPage {
 sink: ConsoleSink = new ConsoleSink()
 onFailure(error: Error): void { this.sink.report(error) }
}
